B="BK-741"
C=[
("S15",4153,4175,"الآلة الكاتبة تترك بصمة ميكانيكية: نوعها أولاً ثم الآلة بعينها","يوضح الكتاب أن الاعتقاد القديم بأن الكتابة الآلية لا تُنسب كان خاطئاً: لكل نوع وطراز خصائص عامة، وكل آلة بعينها تكتسب مع الاستعمال عيوباً خاصة في الحروف. المنهج يبدأ من الأعم (النوع) إلى الأخص (الآلة).","في الألغاز: رسالة مطبوعة تُسأل أولاً: ما نوع الطابعة؟ ثم: هل تحمل عيوباً خاصة تربطها بجهاز معين؟","العيوب التي تدل على آلة بعينها قد تتغير بالصيانة أو التلف مع الزمن.","الرسالة المطبوعة لا يمكن تتبعها.","13-15","safe","lab_limits",["KO-FC-04-017","KO-FC-04-016"],["خصائص عامة","عيب خاص"]),
("S15",4179,4192,"الأصل غير النسخة: الفحص يحتاج الوثيقة الأصلية وعينات من الآلة المشتبه بها","يشترط الكتاب في فحص الآلة الكاتبة أن تكون الوثيقة الأصل لا صورة، لأن التصوير والنسخ بالكربون يغيّران صفات الحرف. وتؤخذ عينات من الآلة المشتبه بها بنفس ظروف الكتابة الأصلية.","اسأل في أي مقارنة: هل لدينا الأصل؟ وهل جُمعت العينات بظروف مشابهة؟","الفحص على نسخة يضعف الاستنتاج.","","16-18","safe","lab_limits",["KO-FC-04-017","KO-FC-04-026"],["أصل ونسخة","عينة مقارنة"]),
("S15",4193,4223,"قياس الحروف ومقارنتها يعطي تشابهاً لا هوية","يعرض الكتاب فكرة قياس أبعاد مواضع في الحرف بعد تكبيره والمقارنة مع أرشيف نماذج الآلات، وإذا اتفق عدد من القياسات مع علامات تلف مشتركة قيل إن الكتابتين من آلة واحدة. نذكر الفكرة فقط دون إجراءات القياس.","اسأل: كم علامة اتفقت؟ وهل هي علامات عامة أم تلف مميّز؟ ومن راجع المقارنة؟","القياسات المتفقة قد تشترك فيها آلات من نفس الطراز.","","16-18","conceptual","lab_limits",["KO-FC-04-016","KO-FC-04B-005","KO-FC-04-031"],["قياس","مقارنة مجهرية"]),
("S15",4224,4226,"عمر الكتابة الآلية لا يُقدَّر بالطريقة نفسها للحبر","يقرر الكتاب أن طرق تقدير عمر كتابة الآلة الكاتبة أصعب لأن مادة الشريط لا تتغير بنفس الطريقة، لكن معرفة تاريخ تلف حرف معين في الآلة قد تعطي حداً زمنياً أدنى للمستند.","ابحث عن تغيرات الآلة المعروفة التاريخ لتحصل على حد أدنى لا تاريخ دقيق.","التاريخ الناتج حد أدنى أو أقصى وليس لحظة الكتابة.","","16-18","conceptual","timing",["KO-FC-04-021","KO-FC-04-017"],["حد زمني","تلف حرف"]),
("S15",4227,4240,"أسلوب الطباعة عادة الكاتب: الهوامش والمسافات وطريقة الضغط","يذكر الكتاب أن طريقة استعمال الآلة (بإصبع أو بعشرة، تباعد الأسطر، الهوامش) تحمل بصمة سلوكية للكاتب تساعد على مقارنة نصين. هذه عادات قابلة للتقليد والتغيير.","قارن العادات الطباعية بين نصين واكتب ما يتفق وما يختلف من غير الجزم.","العادات تتغير بتغير الحالة والجهاز.","","13-15","safe","lab_limits",["KO-FC-04-017","KO-RS-06-004"],["عادة كتابة","تقليد"]),
("S15",4241,4252,"الورق له خصائص تميّزه: المادة واللون والسمك والوزن والعلامة","يشرح الكتاب أن أنواع الورق تتميز بتركيبها وسمكها ووزنها وعلاماتها، ويُقارن ورق رسالة مجهولة بورق عند مشتبه. تطابق النوع يدعم الاحتمال لكنه لا يحدد ورقة بعينها لأن النوع الواحد يوجد بكميات كبيرة.","في الألغاز: قيمة ورقة التهديد في ربطها بمصدر أو دفعة، لا بشخص.","ورق من نوع شائع لا يدل على مصدر بعينه.","نفس الورق يعني نفس الشخص.","13-15","safe","lab_limits",["KO-FC-04-019","KO-RS-06-010"],["ورق","نسبة الأساس"]),
("S16",4253,4260,"مضاهاة الخط العربي ترتكز على فكرة الفردية","يذكر الكتاب أن الخط اليدوي لكل كاتب مجموعة خصائص يندر أن تجتمع في كاتبين. الفكرة تقودنا إلى مقارنة الخصائص المتكررة الثابتة لا إلى مجرد التشابه الشكلي.","نظّم أي مقارنة كخصائص ثابتة تتكرر عند الكاتب، وقارنها مع النص المجهول.","القول بأن الخط لا يتكرر مطلقاً أقوى مما تدعمه الأبحاث الحديثة، فالتقرير الجيد يعبر بدرجات الدعم.","كل خط فريد ويمكن الجزم بنسبته بيقين.","16-18","conceptual","lab_limits",["KO-FC-04-017","KO-FC-04B-004","KO-FC-04B-005"],["فردية الخط","خصائص ثابتة"]),
("S16",4270,4284,"الخط يحمل خصائص عامة (لغة، مهنة، مدرسة) وخاصة (فرد) ولا يجوز الخلط","يقسم الكتاب مميزات الكتابة إلى طبقات: ما يشترك فيه ناطقو اللغة أو أبناء مهنة أو مدرسة، وما ينفرد به الفرد. الخطأ الشائع أن تُعدّ صفة عامة دليلاً على كاتب بعينه.","اسأل لكل صفة مشتركة: كم شخصاً قد يشاركه فيها؟ وما ثباتها عند الكاتب؟","غياب إحصاءات معيارية لتكرار الصفات يحد من قوة الاستنتاج.","التشابه في الشكل العام يكفي لنسبة الخط.","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04B-005","KO-RS-06-010"],["صفة عامة","صفة فردية"]),
("S16",4290,4312,"مستوى الكتابة وأخطاؤها الإملائية جزء من صورة الكاتب","يعد الكتاب مستوى الجودة والإملاء واللغة في النص عنصراً في المقارنة. الأخطاء المتكررة غير المقصودة تميّز الكاتب، أما الخطأ المقصود فقد يكون تمويهاً.","لاحظ الأخطاء التي تتكرر بغير داعٍ ثم اسأل هل هي طبيعية أم مصطنعة.","الكاتب قد يصطنع الخطأ ليبعد عن نفسه الشبهة.","","13-15","safe","witness_reliability",["KO-FC-04B-004","KO-RS-05-007"],["أخطاء إملائية","تمويه"]),
("S16",4328,4332,"أوراق المقارنة هي أساس المضاهاة: ضعفها يضعف النتيجة","يؤكد الكتاب أن الفاحص يعتمد على نماذج معروفة النسب، وأن قصورها في العدد أو النوع يقلل دقة المضاهاة وقد يضلل. سلامة العينة المرجعية شرط لسلامة الاستنتاج.","قبل قراءة أي تقرير خطوط، اسأل: ما النماذج المرجعية؟ كم عددها؟ من أين جاءت؟","نتيجة جيدة على نماذج رديئة تبقى ضعيفة.","","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04-031"],["نماذج مرجعية","جودة العينة"]),
("S16",4333,4348,"نموذج المقارنة المقبول قانوناً نوع، والمقبول فنياً نوع آخر","يفرق الكتاب بين شروط قانونية لقبول النموذج (أن يكون من محرر رسمي أو معترف به) وشروط فنية (معاصرة، طبيعية، تماثل الأداة). النموذج قد يحقق الأولى ولا يحقق الثانية.","اطرح سؤالين: هل هذا النموذج مقبول إجرائياً؟ وهل هو صالح علمياً؟","القاعدة القانونية تخص النظام المذكور.","","16-18","conceptual","reporting",["KO-FC-04B-004","KO-FC-04-031"],["نموذج مقبول","صلاحية فنية"]),
("S16",4356,4365,"كتابة طبيعية أم متصنعة: النموذج المتصنع يُستبعد","يصنف الكتاب أوراق المقارنة بحسب طبيعتها، من خط طبيعي كامل إلى متصنع كامل ويستبعد المتصنع لأنه لا يعكس المميزات الحقيقية. تحقق من ذلك يتم بمقارنة أجزاء الكتابة التي لم تتدخل فيها الإرادة.","في الألغاز: اكتشاف تصنع الكاتب جزء من القصة؛ قارن بين سطره الأول المتأني وسطره الأخير المتعجل.","التمييز بين الطبيعي والمتصنع يحتاج خبرة ويخطئ.","","16-18","conceptual","witness_reliability",["KO-FC-04B-004","KO-RS-05-007"],["تصنع","كتابة طبيعية"]),
("S16",4366,4388,"معاصرة النماذج: الخط يتغير مع العمر والمرض والتعليم","يشرح الكتاب أن خط الشخص يتطور مع مراحل التعلم والعمر ويتأثر بالمرض والإصابة وتغيير البيئة، ولذلك تقارن المستندات بنماذج من الفترة الزمنية القريبة. المثل الأمثل: نماذج قبل وبعد تاريخ المستند.","اطلب نماذج من قبل التاريخ المدون وبعده بمدة قصيرة بدل نموذج حديث وحيد.","نموذج بعيد زمنياً قد يعطي اختلافاً مصدره الزمن لا الكاتب.","","16-18","conceptual","timing",["KO-FC-04B-004","KO-FC-04-021"],["معاصرة","تطور الخط"]),
("S16",4389,4399,"تماثل الأداة والورق والسطح في نماذج المقارنة","يوصي الكتاب بأن تتشابه ظروف كتابة النموذج مع ظروف المستند المجهول (نوع القلم، الورق، السطح، حتى كون الكتابة في مركبة متحركة). كلما اقتربت الظروف زادت قيمة المقارنة.","وثّق ظروف أخذ العينة (القلم، الورقة، الوضعية).","الظروف المثالية لا تتوفر دائماً.","","13-15","safe","scene_documentation",["KO-FC-04B-004","KO-FC-04-026"],["ظروف الكتابة"]),
("S16",4408,4434,"الاستكتاب بالإملاء وعلى مراحل لتقليل التصنع","يصف الكتاب إجراء أخذ عينة كتابة من المشتبه به بحضور المحقق وبإملاء ودون إظهار المستند أمامه، ومن مراحل: كتابة حرة، ثم عبارات فيها كلمات المستند، ثم نفس النص، ثم باليد الأخرى، مع تكرار الجلسة إن ظهر التصنع. الغاية قياس الكتابة الطبيعية.","كجزء من التحقيق: لا تعطِ المشتبه به المستند ليقلده، بل أملِ عليه.","الاستكتاب تحت الضغط قد يغير الخط نفسه.","","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04-027"],["استكتاب","إملاء"]),
("S16",4435,4451,"المقارنة مراحل: الجرة والمستوى والأسلوب والمسار","يرتب الكتاب دراسة الخط بمراحل: تكوين الجرات، المستوى، الأسلوب (هوامش، أسطر، فواصل)، ثم مسار القلم في الحروف بحسب موضعها في الكلمة. مقارنة الحرف بنفسه في الموضع نفسه شرط.","قارن الشيء بنظيره في الموضع نفسه، لا حرفاً أوسط بحرف آخر.","كثرة المعايير لا تلغي ذاتية التقدير.","","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04-017"],["مقارنة منظمة","موضع الحرف"]),
("S16",4452,4460,"أربع نتائج ممكنة للمقارنة: اتفاق، اختلاف، تشابه عام، تطابق مريب","يعدد الكتاب أربعة احتمالات: اتفاق كامل في الخصائص الفردية، اختلاف ثابت في ميزة واحدة على الأقل، تشابه في الصفات العامة فقط، وتطابق تام يوحي بأن إحدى الكتابتين منسوخة. التطابق الحرفي المبالغ فيه يدعو للشك لا للاطمئنان.","استعمل هذه الأربعة كقائمة نتائج مقبولة في الألغاز ولا تكتفِ بنعم أو لا.","الخلاف في ميزة واحدة لا يكفي دائماً؛ المعيار الأقوى هو الثبات والتكرار.","التطابق التام دليل قاطع على الكاتب نفسه.","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04B-005","KO-FC-04-031"],["اتفاق","تطابق مريب"]),
]
